// Attribute main-chunk bytes to source files via the sourcemap (content vs libs vs app code).
import fs from 'node:fs'
import { SourceMapConsumer } from 'source-map'
const dir = 'build-sm/assets/'
const main = fs.readdirSync(dir).find((f) => /^index-.*\.js$/.test(f))
const code = fs.readFileSync(dir + main, 'utf8')
const map = JSON.parse(fs.readFileSync(dir + main + '.map', 'utf8'))
const lines = code.split('\n')
const bytesBySource = {}
await SourceMapConsumer.with(map, null, (c) => {
  // walk mappings, attribute generated byte ranges to the source of the segment start
  let prev = null
  c.eachMapping((m) => {
    if (prev && prev.generatedLine === m.generatedLine) {
      const len = m.generatedColumn - prev.generatedColumn
      const k = prev.source || '(none)'
      bytesBySource[k] = (bytesBySource[k] || 0) + len
    } else if (prev) {
      const len = lines[prev.generatedLine - 1].length - prev.generatedColumn
      const k = prev.source || '(none)'
      bytesBySource[k] = (bytesBySource[k] || 0) + len
    }
    prev = { generatedLine: m.generatedLine, generatedColumn: m.generatedColumn, source: m.source }
  }, null, SourceMapConsumer.GENERATED_ORDER)
  if (prev) bytesBySource[prev.source || '(none)'] += lines[prev.generatedLine - 1].length - prev.generatedColumn
})
const groups = {}
const add = (g, n) => (groups[g] = (groups[g] || 0) + n)
for (const [s, n] of Object.entries(bytesBySource)) {
  if (/\/content\/(far|aud|reg|tcp)\//.test(s)) add('content:' + s.match(/\/content\/(\w+)\//)[1], n)
  else if (/\/content\//.test(s)) add('content:other(sections,glossary)', n)
  else if (/node_modules\/(\.pnpm\/)?([^/]+(\/[^/]+)?)/.test(s)) {
    const m = s.match(/node_modules\/((@[^/]+\/)?[^/]+)/)
    add('lib:' + m[1], n)
  } else if (/\/src\//.test(s)) add('app:src', n)
  else add('other:' + s.slice(-40), n)
}
const total = code.length
const sorted = Object.entries(groups).sort((a, b) => b[1] - a[1])
const contentTotal = sorted.filter(([k]) => k.startsWith('content')).reduce((s, [, n]) => s + n, 0)
console.log('main chunk', main, 'bytes', total)
console.log('content share', contentTotal, (100 * contentTotal / total).toFixed(1) + '%')
for (const [k, n] of sorted.slice(0, 22)) console.log(String(n).padStart(9), (100 * n / total).toFixed(1).padStart(5) + '%', k)
fs.writeFileSync('out/bundle-composition.json', JSON.stringify({ main, total, contentTotal, groups: sorted }, null, 2))
